#include "portable_png.hpp"
#include <nlohmann/json.hpp>
#include <iomanip>
#include <iostream>
using J=nlohmann::json;using namespace pas::portable_png;
int main(int argc,char**argv){try{if(argc!=4||std::filesystem::exists(argv[3]))throw std::runtime_error("usage OLD_CARDS_JSON FRAME_ROOT FRESH_REPORT");std::ifstream in(argv[1]);const auto old=J::parse(in);if(old.at("cards").size()!=4)throw std::runtime_error("four original cards required");J checks=J::array();int failed=0;for(const auto&card:old.at("cards")){std::ostringstream file;file<<"frames/frame-"<<std::setw(6)<<std::setfill('0')<<card.at("ordinal").get<int>()<<".png";const auto png=read(std::filesystem::path(argv[2])/file.str());if(digest(png)!=card.at("source_sha256").get<std::string>())throw std::runtime_error("original card source SHA mismatch");const auto rgb=decode(png);for(const auto&sample:card.at("samples")){const int x=sample.at("point").at(0),y=sample.at("point").at(1);if(x<0||x>=1280||y<0||y>=720)throw std::runtime_error("sample bounds");const auto at=(std::size_t(y)*1280+x)*3;const std::array<int,3>actual={rgb[at],rgb[at+1],rgb[at+2]};const bool pass=J(actual)==sample.at("rgb");failed+=!pass;checks.push_back({{"card",card.at("name")},{"point",sample.at("point")},{"expected_WIC_rgb",sample.at("rgb")},{"actual_libpng_rgb",actual},{"pass",pass}});}}
 J result={{"schema","pas.portable-decoder-old-WIC-samples.v1"},{"assertions",checks.size()},{"failed",failed},{"checks",checks},{"old_cards_sha256",pas::evidence::sha256(argv[1])},{"device_endpoints",0}};std::ofstream out(argv[3]);out<<result.dump(2)<<'\n';std::cout<<"original WIC sample checks="<<checks.size()<<" failed="<<failed<<'\n';return failed?1:0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
